 @Test void changeKeepsAppointmentStatesPublicErrorAndAllApprovedTransitions(){writable("REC");Map<String,List<String>> transitions=Map.of("REQUESTED",List.of("RESERVED","CANCELLED"),"RESERVED",List.of("RESERVED","CONFIRMED","CANCELLED"),"CONFIRMED",List.of("RESERVED","WAITING","CANCELLED"),"WAITING",List.of("CALLED","WITHDRAWN"),"CALLED",List.of("IN_CARE","WAITING","WITHDRAWN"),"IN_CARE",List.of("COMPLETED"));for(var entry:transitions.entrySet())for(String status:entry.getValue()){var current=appointment();current.put("status",entry.getKey());rows(List.of(current));rows(List.of(changed(current,status,null,null)));assertEquals(status,store.change(request,APPOINTMENT,new Change(1,status,null,null)).get("status"));}var current=appointment();current.put("status","COMPLETED");rows(List.of(current));var error=assertThrows(ApiException.class,()->store.change(request,APPOINTMENT,new Change(1,"RESERVED",null,null)));assertEquals("INVALID_TRANSITION",error.code);assertEquals(409,error.status);}
