 @Test void mutationSqlErrorsCommitAndOuterCancellationNeverRetryOrFallback(){writable("REC");var p=reserveInput(future(),1800,"RESERVED");for(int vendor:List.of(51000,51001,51002,51003,51004,51005)){doThrow(new RuntimeException(new java.sql.SQLException("private-driver-canary",null,vendor))).when(executor).execute(eq(SqlServerProcedure.APPOINTMENT_RESERVE),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.reserve(request,p,"synthetic-key-001",false));assertEquals(vendor==51000?400:vendor==51002?404:vendor==51003||vendor==51005?409:403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("private-driver"));}verify(executor,times(6)).execute(eq(SqlServerProcedure.APPOINTMENT_RESERVE),any(),any(Object[].class));reset(executor);doAnswer(inv->new SqlServerExecutor.Result(List.of(List.of(reserved(p))),List.of())).when(executor).execute(any(),any(),any(Object[].class));manager.failCommit=true;safe(()->store.reserve(request,p,"synthetic-key-001",false));assertThrows(RuntimeException.class,()->manager.outer(()->{store.reserve(request,p,"synthetic-key-001",false);throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());}

 @Test void reserveNanosecondsHashOriginalDtoWhileBodyAndResultUseLegacySixDecimals(){writable("REC");var start=future().plusNanos(789);var p=reserveInput(start,1800,"RESERVED");doAnswer(inv->{Object[] a=(Object[])inv.getRawArguments()[2];var row=reserved(p);row.put("id",a[0]);row.put("startsAt",start.truncatedTo(java.time.temporal.ChronoUnit.MICROS).toString());row.put("endsAt",p.endsAt().truncatedTo(java.time.temporal.ChronoUnit.MICROS).toString());assertEquals(Checks.hash(mapper.writeValueAsString(p)),a[3]);var body=mapper.readValue((String)a[1],Map.class);assertEquals(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSSSSS").withZone(ZoneOffset.UTC).format(start),body.get("startsAt"));assertNotEquals(Checks.hash(mapper.writeValueAsString(reserveInput(start.truncatedTo(java.time.temporal.ChronoUnit.MICROS),1800,"RESERVED"))),a[3]);return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}).when(executor).execute(any(),any(),any(Object[].class));assertEquals(start.truncatedTo(java.time.temporal.ChronoUnit.MICROS).toString(),store.reserve(request,p,"synthetic-key-001",false).get("startsAt"));}
 @Test void replayKeepsCurrentStateAndRescheduledTimesButNeverChangesIdentityFields(){writable("REC");var p=reserveInput(future(),1800,"RESERVED");var row=reserved(p);row.put("status","CONFIRMED");row.put("startsAt",p.startsAt().plusSeconds(86400).toString());row.put("endsAt",p.endsAt().plusSeconds(86400).toString());row.put("revision",3);rows(List.of(row));var result=store.reserve(request,p,"synthetic-key-001",false);assertEquals(APPOINTMENT,result.get("id"));assertEquals("CONFIRMED",result.get("status"));assertEquals(3,result.get("revision"));assertEquals(1,calls.size());}
 @Test void newReserveResultMustMatchGeneratedIdMutationAndMapperFailureIsSafe(){writable("REC");var p=reserveInput(future(),1800,"RESERVED");doAnswer(inv->{Object[] a=(Object[])inv.getRawArguments()[2];var row=reserved(p);row.put("id",a[0]);row.put("status","CONFIRMED");return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}).when(executor).execute(any(),any(),any(Object[].class));safe(()->store.reserve(request,p,"synthetic-key-001",false));var broken=mock(ObjectMapper.class);doThrow(new IllegalStateException("private mapper canary")).when(broken).writeValueAsString(any());clearInvocations(executor);safe(()->new SqlServerSchedulingStore(executor,manager,broken).reserve(request,p,"synthetic-key-001",false));verifyNoInteractions(executor);}
 @Test void changeMutationErrorsAndCommitFailureRollbackWithoutRetryOrPostRead(){writable("REC");for(int vendor:List.of(51000,51001,51002,51003,51004,51005)){rows(List.of(appointment()));doThrow(new RuntimeException(new java.sql.SQLException("private change canary",null,vendor))).when(executor).execute(eq(SqlServerProcedure.APPOINTMENT_CHANGE),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.change(request,APPOINTMENT,new Change(1,"CONFIRMED",null,null)));assertEquals(vendor==51000?400:vendor==51002?404:vendor==51003||vendor==51005?409:403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));assertEquals("rollback",manager.events.getLast());}verify(executor,times(6)).execute(eq(SqlServerProcedure.APPOINTMENT_GET),any(),eq(APPOINTMENT));verify(executor,times(6)).execute(eq(SqlServerProcedure.APPOINTMENT_CHANGE),any(),any(Object[].class));reset(executor);doAnswer(inv->{boolean read=inv.getArgument(0)==SqlServerProcedure.APPOINTMENT_GET;return new SqlServerExecutor.Result(List.of(List.of(read?appointment():changed(appointment(),"CONFIRMED",null,null))),List.of());}).when(executor).execute(any(),any(),any(Object[].class));manager.failCommit=true;safe(()->store.change(request,APPOINTMENT,new Change(1,"CONFIRMED",null,null)));assertThrows(RuntimeException.class,()->manager.outer(()->{store.change(request,APPOINTMENT,new Change(1,"CONFIRMED",null,null));throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());verify(executor,times(2)).execute(eq(SqlServerProcedure.APPOINTMENT_GET),any(),eq(APPOINTMENT));verify(executor,times(2)).execute(eq(SqlServerProcedure.APPOINTMENT_CHANGE),any(),any(Object[].class));}
 @Test void changeEmptyMultipleOrMissingResultSetsAfterWriteAreDatabaseErrors(){writable("REC");for(var result:List.of(new SqlServerExecutor.Result(List.of(List.of()),List.of()),new SqlServerExecutor.Result(List.of(List.of(changed(appointment(),"CONFIRMED",null,null),changed(appointment(),"CONFIRMED",null,null))),List.of()),new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of(changed(appointment(),"CONFIRMED",null,null)),List.of()),List.of()))){rows(List.of(appointment()));results.add(result);safe(()->store.change(request,APPOINTMENT,new Change(1,"CONFIRMED",null,null)));assertEquals("rollback",manager.events.getLast());}}

